POST /v1/emails.go:
import (
	"context"

	coss "github.com/cosscom/coss-go"
	cossclient "github.com/cosscom/coss-go/client"
)

client := cossclient.NewClient() // option.WithAPIKey(…) or COSS_API_KEY

request := &coss.SendEmailBody{
    IdempotencyKey: coss.String(
        "welcome-user-123",
    ),
    Body: &coss.SendEmailRequest{
        From: "Acme <onboarding@acme.com>",
        To: &coss.SendEmailRequestTo{
            String: "user@example.com",
        },
        Subject: coss.String(
            "Welcome to Acme",
        ),
        HTML: coss.String(
            "<p>Thanks for signing up!</p>",
        ),
        Tags: []*coss.SendEmailRequestTagsItem{
            &coss.SendEmailRequestTagsItem{
                Name: "template",
                Value: "welcome",
            },
        },
        Category: coss.String(
            "onboarding",
        ),
    },
}
client.Email.Send(
    context.TODO(),
    request,
)

POST /v1/emails.java:
import com.coss.Coss;
import com.coss.resources.email.requests.SendEmailBody;
import com.coss.types.SendEmailRequest;
import com.coss.types.SendEmailRequestTagsItem;
import com.coss.types.SendEmailRequestTo;
import java.util.Arrays;
import java.util.Optional;

Coss client = Coss.builder().build(); // .apiKey(…) or COSS_API_KEY

client.email().send(
    SendEmailBody
        .builder()
        .body(
            SendEmailRequest
                .builder()
                .from("Acme <onboarding@acme.com>")
                .to(
                    SendEmailRequestTo.of("user@example.com")
                )
                .subject("Welcome to Acme")
                .html("<p>Thanks for signing up!</p>")
                .tags(
                    Optional.of(
                        Arrays.asList(
                            SendEmailRequestTagsItem
                                .builder()
                                .name("template")
                                .value("welcome")
                                .build()
                        )
                    )
                )
                .category("onboarding")
                .build()
        )
        .idempotencyKey("welcome-user-123")
        .build()
);

