                    .to(
                        SendEmailRequestTo.of("grace@example.com")
                    )
                    .subject("Your weekly summary")
                    .html("<p>Hi Grace, here is your week.</p>")
                    .category("digest")
                    .build()
            )
        )
        .idempotencyKey("welcome-user-123")
        .build()
);

