                        .build(),
                    TemplateContentInput
                        .builder()
                        .locale("de")
                        .subject("Willkommen, {{first_name}}")
                        .html("<p>Hallo {{first_name}}, danke für deine Anmeldung!</p>")
                        .build()
                )
            )
        )
        .build()
);

