import com.coss.Coss;
import com.coss.resources.email.segments.requests.CreateSegmentRequest;
import com.coss.types.SegmentFilter;
import com.coss.types.SegmentFilterConditionsItem;
import com.coss.types.SegmentFilterConditionsItemConditions;
import com.coss.types.SegmentFilterConditionsItemConditionsConditionsItem;
import com.coss.types.SegmentFilterConditionsItemConditionsConditionsItemAudience;
import com.coss.types.SegmentFilterConditionsItemConditionsConditionsItemAudienceOp;
import com.coss.types.SegmentFilterConditionsItemConditionsConditionsItemEmail;
import com.coss.types.SegmentFilterConditionsItemConditionsConditionsItemEmailOp;
import com.coss.types.SegmentFilterConditionsItemConditionsMatch;
import com.coss.types.SegmentFilterConditionsItemKey;
import com.coss.types.SegmentFilterConditionsItemKeyField;
import com.coss.types.SegmentFilterConditionsItemKeyOp;
import com.coss.types.SegmentFilterConditionsItemKeyValue;
import com.coss.types.SegmentFilterMatch;
import java.util.Arrays;
import java.util.Optional;

Coss client = Coss.builder().build(); // .apiKey(…) or COSS_API_KEY

client.email().segments().create(
    CreateSegmentRequest
        .builder()
        .name("Pro customers")
        .filter(
            SegmentFilter
                .builder()
                .version(1.0)
                .match(SegmentFilterMatch.ALL)
                .conditions(
                    Arrays.asList(
                        SegmentFilterConditionsItem.of(
                            SegmentFilterConditionsItemKey
                                .builder()
                                .field(SegmentFilterConditionsItemKeyField.PROPERTY)
                                .key("plan")
                                .op(SegmentFilterConditionsItemKeyOp.EQ)
                                .value(
                                    Optional.of(
                                        SegmentFilterConditionsItemKeyValue.of("pro")
                                    )
                                )
                                .build()
                        ),
                        SegmentFilterConditionsItem.of(
                            SegmentFilterConditionsItemConditions
                                .builder()
                                .match(SegmentFilterConditionsItemConditionsMatch.ANY)
                                .conditions(
                                    Arrays.asList(
                                        SegmentFilterConditionsItemConditionsConditionsItem.email(
                                            SegmentFilterConditionsItemConditionsConditionsItemEmail
                                                .builder()
                                                .op(SegmentFilterConditionsItemConditionsConditionsItemEmailOp.ENDS_WITH)
                                                .value("@acme.com")
                                                .build()
                                        ),
                                        SegmentFilterConditionsItemConditionsConditionsItem.audience(
                                            SegmentFilterConditionsItemConditionsConditionsItemAudience
                                                .builder()
                                                .op(SegmentFilterConditionsItemConditionsConditionsItemAudienceOp.IN)
                                                .audienceId("aud_01k7c8m4q2f3e9v6t5r1n0p8yz")
                                                .build()
                                        )
                                    )
                                )
                                .build()
                        )
                    )
                )
                .build()
        )
        .build()
);

